反向代理是什么？如果你想要知道反向代理是什么的话，你可以看看腾讯云开发者社区的这篇文章：终于有人把正向代理和反向代理解释的明明白白了！，我觉得解释得还蛮通俗易懂的。
CF Worker打开CloudFlare，我们在 CloudFlare 账号的控制面板左边栏往下滑，找到“计算（Workers）”，点击它进入 Workers 页面。

点击右上角的“创建”按钮，进入下面这个页面

选择“从hello world 开始”，就进到了部署页面。

部署成功之后它会自动跳转到以下页面：

我们点“编辑代码”。进入下面这个页面

将下方代码全部粘贴到代码框里：
// 反代目标网站.
const upstream = &#x27;google.com&#x27;

// 反代目标网站的移动版.
const upstream_mobile = &#x27;google.com&#x27;

// 访问区域黑名单（按需设置）.
const blocked_region = [&#x27;TK&#x27;]

// IP地址黑名单（按需设置）.
const blocked_ip_address = [&#x27;0.0.0.0&#x27;, &#x27;127.0.0.1&#x27;]

// 路径替换.
const replace_dict = &#123;
&#x27;$upstream&#x27;: &#x27;$custom_domain&#x27;,
&#x27;//archiveofourown.org&#x27;: &#x27;&#x27;
&#125;

addEventListener(&#x27;fetch&#x27;, event =&gt; &#123;
event.respondWith(fetchAndApply(event.request));
&#125;)

async function fetchAndApply(request) &#123;

const region = request.headers.get(&#x27;cf-ipcountry&#x27;).toUpperCase();
const ip_address = request.headers.get(&#x27;cf-connecting-ip&#x27;);
const user_agent = request.headers.get(&#x27;user-agent&#x27;);

let response = null;
let url = new URL(request.url);
let url_host = url.host;

if (url.protocol == &#x27;http:&#x27;) &#123;
    url.protocol = &#x27;https:&#x27;
    response = Response.redirect(url.href);
    return response;
&#125;

if (await device_status(user_agent)) &#123;
    var upstream_domain = upstream;
&#125; else &#123;
    var upstream_domain = upstream_mobile;
&#125;

url.host = upstream_domain;

if (blocked_region.includes(region)) &#123;
    response = new Response(&#x27;Access denied: WorkersProxy is not available in your region yet.&#x27;, &#123;
        status: 403
    &#125;);
&#125; else if(blocked_ip_address.includes(ip_address))&#123;
    response = new Response(&#x27;Access denied: Your IP address is blocked by WorkersProxy.&#x27;, &#123;
        status: 403
    &#125;);
&#125; else&#123;
    let method = request.method;
    let request_headers = request.headers;
    let new_request_headers = new Headers(request_headers);

    new_request_headers.set(&#x27;Host&#x27;, upstream_domain);
    new_request_headers.set(&#x27;Referer&#x27;, url.href);

    let original_response = await fetch(url.href, &#123;
        method: method,
        headers: new_request_headers
    &#125;)

    let original_response_clone = original_response.clone();
    let original_text = null;
    let response_headers = original_response.headers;
    let new_response_headers = new Headers(response_headers);
    let status = original_response.status;

    new_response_headers.set(&#x27;cache-control&#x27; ,&#x27;public, max-age=14400&#x27;)
    new_response_headers.set(&#x27;access-control-allow-origin&#x27;, &#x27;*&#x27;);
    new_response_headers.set(&#x27;access-control-allow-credentials&#x27;, true);
    new_response_headers.delete(&#x27;content-security-policy&#x27;);
    new_response_headers.delete(&#x27;content-security-policy-report-only&#x27;);
    new_response_headers.delete(&#x27;clear-site-data&#x27;);

    const content_type = new_response_headers.get(&#x27;content-type&#x27;);
    if (content_type.includes(&#x27;text/html&#x27;) &amp;&amp; content_type.includes(&#x27;UTF-8&#x27;)) &#123;
        original_text = await replace_response_text(original_response_clone, upstream_domain, url_host);
    &#125; else &#123;
        original_text = original_response_clone.body
    &#125;

    response = new Response(original_text, &#123;
        status,
        headers: new_response_headers
    &#125;)
&#125;
return response;
&#125;

async function replace_response_text(response, upstream_domain, host_name) &#123;
let text = await response.text()

var i, j;
for (i in replace_dict) &#123;
    j = replace_dict[i]
    if (i == &#x27;$upstream&#x27;) &#123;
        i = upstream_domain
    &#125; else if (i == &#x27;$custom_domain&#x27;) &#123;
        i = host_name
    &#125;

    if (j == &#x27;$upstream&#x27;) &#123;
        j = upstream_domain
    &#125; else if (j == &#x27;$custom_domain&#x27;) &#123;
        j = host_name
    &#125;

    let re = new RegExp(i, &#x27;g&#x27;)
    text = text.replace(re, j);
&#125;
return text;
&#125;


async function device_status (user_agent_info) &#123;
var agents = [&quot;Android&quot;, &quot;iPhone&quot;, &quot;SymbianOS&quot;, &quot;Windows Phone&quot;, &quot;iPad&quot;, &quot;iPod&quot;];
var flag = true;
for (var v = 0; v &lt; agents.length; v++) &#123;
    if (user_agent_info.indexOf(agents[v]) &gt; 0) &#123;
        flag = false;
        break;
    &#125;
&#125;
return flag;
&#125;

粘贴好后按需修改下方参数const upstream &#x3D; ‘反代目标网站’const upstream_mobile &#x3D; ‘反代目标网站的移动版’const blocked_region &#x3D; [‘访问区域黑名单（按需设置）’]const blocked_ip_address &#x3D; [‘IP地址黑名单（按需设置）’, ‘127.0.0.1’]const replace_dict &#x3D; 路径替换修改好之后，点击部署，部署好了之后就可以退出了。
自定义域名再项目主页点击设置，我们看上面“域和路由”这一栏，这里我们就可以看到这个 Worker 默认绑定的域名了，但是呢这个域名现在被中国墙了，所以我们要绑定一下我们自己的域名。
这个域名如果大家自己有的话当然最好，如果没有的话可以看看我这篇文章，免费获取一个二级的域名。
如何申请免费域名并托管到CloudFlare
我们点击“添加”

选择“自定义域”,在这里输入你希望绑定的域名。
点击“添加域”，CloudFlare 会自动帮你添加一个 CNAME 记录。
注意：输入的域名一定要绑定在 CloudFlare 你的账号下面，否则就不能绑定。
现在就等 DNS 生效就行了，一般来说几分钟就能好，最多不会超过48小时。DNS 生效了就可以访问这个域名啦！
OK，部署完成噜，访问自定义域名即可使用了哦！
